#!/usr/bin/env python3
"""news-23 b218 heroes-scene entry renderer (stdlib only).

Writes the pre-rendered 1024x1024 front page to
os.path.join(os.environ.get("MAKEFUN_OUTPUT_DIR", "out"), "entry.png")
after strict structural validation of the embedded PNG payload.

The payload is base64 decoded with validate=True, so any character outside
the strict base64 alphabet (including whitespace inside the data) is
rejected before validation even starts; the decoded bytes must then pass
signature, IHDR, per-chunk CRC, IDAT decompression, scanline filter,
IEND/trailing-data and explicit sha256/size checks.
"""
